#!/usr/bin/env bash
# Generated by can (epic E06). Idempotent: running it again converges.
# Hand edits are lost; change the generator in core/provider/bootstrap.go.
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive

K3S_VERSION='v1.33.5+k3s1'
SSH_PORT='2222'
POD_CIDR='10.42.0.0/16'
SERVICE_CIDR='10.43.0.0/16'
SWAP_MB='2048'

config_new=''
installer=''
trap 'rm -f "$config_new" "$installer"' EXIT

step() { echo "CAN_STEP: $1"; }
warn() { echo "CAN_WARN: $1"; }

if [ "$(id -u)" -ne 0 ]; then
  echo "CAN_ERROR: must run as root" >&2
  exit 1
fi

step swap
mem_mb=$(awk '/^MemTotal:/ {print int($2/1024)}' /proc/meminfo)
if [ "$mem_mb" -lt 4096 ] && [ -z "$(swapon --show --noheadings)" ]; then
  if [ ! -f /swapfile ]; then
    fallocate -l "${SWAP_MB}M" /swapfile || dd if=/dev/zero of=/swapfile bs=1M count="$SWAP_MB" status=none
    chmod 600 /swapfile
    mkswap /swapfile >/dev/null
  fi
  swapon /swapfile
  grep -q '^/swapfile ' /etc/fstab || echo '/swapfile none swap sw 0 0' >> /etc/fstab
  echo 'vm.swappiness=10' > /etc/sysctl.d/90-can-swap.conf
  sysctl -q -p /etc/sysctl.d/90-can-swap.conf
fi

step firewall
if ! command -v ufw >/dev/null 2>&1; then
  if command -v apt-get >/dev/null 2>&1; then
    apt-get update -qq
    apt-get install -y -qq ufw
  else
    warn "ufw is not available; configure the host firewall manually (allow 22, 80, 443, ${POD_CIDR}, ${SERVICE_CIDR})"
  fi
fi
if command -v ufw >/dev/null 2>&1; then
  ufw default deny incoming
  ufw default allow outgoing
  ufw default allow routed
  ufw allow from '198.51.100.9/32' to any port "$SSH_PORT" proto tcp
  ufw allow 80/tcp
  ufw allow 443/tcp
  # k3s needs pod and service traffic to reach the host (system pods use the API server). What
  # pods may actually reach is narrowed by the node-firewall step below.
  ufw allow from "$POD_CIDR"
  ufw allow from "$SERVICE_CIDR"
  ufw allow in on cni0
  ufw allow in on flannel.1
  # 6443 (k3s API) is not opened to the internet: can reaches it through an SSH tunnel.
  ufw --force enable
fi

step k3s-config
install -d -m 0755 /etc/rancher/k3s
rm -f /etc/rancher/k3s/config.yaml.??????   # leftovers of an interrupted earlier run
config_new=$(mktemp /etc/rancher/k3s/config.yaml.XXXXXX)
cat > "$config_new" <<'CAN_K3S_CONFIG'
node-name: acme
write-kubeconfig-mode: "0600"
secrets-encryption: true
disable:
  - metrics-server
disable-cloud-controller: true
cluster-cidr: 10.42.0.0/16
service-cidr: 10.43.0.0/16
kubelet-arg:
  - fail-swap-on=false
CAN_K3S_CONFIG
chmod 0644 "$config_new"
mv "$config_new" /etc/rancher/k3s/config.yaml
config_new=''
install -d -m 0700 /var/lib/can
want_config=$(sha256sum /etc/rancher/k3s/config.yaml | awk '{print $1}')
applied_config=$(cat /var/lib/can/k3s-config.applied 2>/dev/null || true)

step images
install -d -m 0755 /var/lib/rancher/k3s/agent/images
fetch_image() {
  local name="$1" url="$2" sha="$3" dest tmp
  dest="/var/lib/rancher/k3s/agent/images/${name}"
  if [ -f "$dest" ] && echo "${sha}  ${dest}" | sha256sum -c --status -; then
    return 0
  fi
  tmp="${dest}.part"
  curl -fsSL --retry 5 -o "$tmp" "$url"
  echo "${sha}  ${tmp}" | sha256sum -c --status - || { rm -f "$tmp"; echo "CAN_ERROR: checksum mismatch for ${name}" >&2; return 1; }
  mv "$tmp" "$dest"
}
fetch_pids=()
fetch_image 'can-core.tar.zst' 'https://example.invalid/can-core.tar.zst' 'abababababababababababababababababababababababababababababababab' &
fetch_pids+=("$!")
fetch_image 'traefik.tar' 'https://example.invalid/traefik.tar' 'cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd' &
fetch_pids+=("$!")

step k3s
current=$(k3s --version 2>/dev/null | awk 'NR==1 {print $3}' || true)
if [ "$current" != "$K3S_VERSION" ]; then
  # The installer script is downloaded over TLS but not hash-verified (the
  # version it installs is pinned, the script itself is not).
  installer=$(mktemp)
  curl -fsSL --retry 5 -o "$installer" https://get.k3s.io
  INSTALL_K3S_VERSION="$K3S_VERSION" sh "$installer"
  rm -f "$installer"
  installer=''
elif [ "$applied_config" != "$want_config" ]; then
  # Same version but config.yaml differs from what k3s last started with (or a
  # previous run died before recording it): restart so it takes effect.
  systemctl restart k3s
fi

for pid in ${fetch_pids[@]+"${fetch_pids[@]}"}; do
  wait "$pid"
done

step ready
for _ in $(seq 1 90); do
  nodes=$(k3s kubectl get nodes --no-headers 2>/dev/null || true)
  case "$nodes" in
    *" Ready"*) break ;;
  esac
  sleep 2
done
case "$(k3s kubectl get nodes --no-headers 2>/dev/null || true)" in
  *" Ready"*) ;;
  *) echo "CAN_ERROR: node did not become Ready" >&2; exit 1 ;;
esac

# Pod-to-node isolation (specs/038-node-isolation): NetworkPolicy does not cover it on k3s.
step node-firewall
if ! command -v nft >/dev/null 2>&1; then
  apt-get update -qq
  apt-get install -y -qq nftables
fi
install -d -m 0755 /etc/can/firewall
cat > /usr/local/sbin/can-firewall.new <<'CAN_FIREWALL_SCRIPT'
#!/usr/bin/env bash
# can-firewall: pod-to-node isolation for a single-node k3s server (specs/038-node-isolation).
# Installed by the server bootstrap as /usr/local/sbin/can-firewall; edit it in
# core/provider/hostfw/can-firewall.sh.
#
# It owns ONE nftables table, inet can_isolation, and never flushes anything else. Each chain
# first accepts whatever did not arrive on a pod interface, so traffic from outside (the
# operator's SSH included) is never matched. A drop in this table is final whatever ufw,
# kube-proxy, flannel or kube-router accept in their own chains.
#
#   apply     load the rules (atomic; seeds the trusted pod set when the API answers)
#   sync      refresh the trusted pod set once
#   run       keep the rules loaded and the set current (can-firewall-sync.service)
#   install   apply, verify, write and enable the systemd units; roll back on failure
#   check     print key=value status; exit 0 only when enforcing
#             (on demand: nothing runs it on a schedule or raises an alert)
#   disable   stop enforcing and do not start again at boot (the escape hatch)
#   uninstall disable and remove the units and this script
#   rules     print the ruleset
set -uo pipefail

TABLE_FAMILY=inet
TABLE_NAME=can_isolation
# Interfaces pod traffic arrives on (k3s flannel). Nothing else is ever filtered.
IFACES=${CAN_FW_IFACES:-'"cni0", "flannel.1"'}
POD_BRIDGE=${CAN_FW_POD_BRIDGE:-cni0}
CONF_DIR=${CAN_FW_CONF_DIR:-/etc/can/firewall}
CNI_STATE=${CAN_FW_CNI_STATE:-/var/lib/cni/networks/cbr0}
INTERVAL=${CAN_FW_INTERVAL:-15}
WAIT=${CAN_FW_WAIT:-180}
UNIT_DIR=${CAN_FW_UNIT_DIR:-/etc/systemd/system}
SELF=${CAN_FW_SELF:-/usr/local/sbin/can-firewall}
SYSTEMCTL=${CAN_FW_SYSTEMCTL:-systemctl}
read -r -a KC <<<"${CAN_FW_KUBECTL:-k3s kubectl}"
UNITS=(can-firewall.service can-firewall-sync.service)

log() { echo "can-firewall: $*"; }
err() { echo "CAN_ERROR: can-firewall: $*" >&2; }

# The ruleset. DNS is matched on the port the pod ASKED for (ct original proto-dst): a resolver on
# the host is often reached through DNAT to another port (k3d does this). apply() replaces the
# whole table with this in one transaction (nft -f is atomic), so loading it again converges.
rules() {
  local t="$TABLE_FAMILY $TABLE_NAME"
  cat <<RULES
add table $t
add set $t trusted4 { type ipv4_addr; }
add chain $t input { type filter hook input priority -10; policy accept; }
add chain $t forward { type filter hook forward priority -10; policy accept; }
flush chain $t input
flush chain $t forward
add rule $t input iifname != { $IFACES } accept
add rule $t input ct state established,related ct direction reply accept
add rule $t input icmpv6 type { nd-neighbor-solicit, nd-neighbor-advert, nd-router-solicit } accept
add rule $t input ip saddr @trusted4 tcp dport 6443 accept
add rule $t input ip saddr @trusted4 meta l4proto { tcp, udp } ct original proto-dst 53 accept
add rule $t input counter drop
add rule $t forward iifname != { $IFACES } accept
add rule $t forward ip daddr 169.254.0.0/16 counter drop
add rule $t forward ip6 daddr { fd00:ec2::254, fe80::a9fe:a9fe } counter drop
RULES
}

# Namespaces besides kube-system whose pods may reach the API server, one per line in
# $CONF_DIR/trusted-namespaces. Module namespaces are ignored.
extra_namespaces() {
  [ -f "$CONF_DIR/trusted-namespaces" ] || return 0
  grep -E '^[a-z0-9]([a-z0-9-]*[a-z0-9])?$' "$CONF_DIR/trusted-namespaces" | grep -v '^mod-' || true
}

# Every unfinished pod: namespace|app.kubernetes.io/name|hostNetwork|podIP|deletionTimestamp.
# Finished pods keep their podIP in status although the address is free again: exclude them.
all_pods() {
  "${KC[@]}" --request-timeout=5s get pods --all-namespaces \
    --field-selector=status.phase!=Succeeded,status.phase!=Failed \
    -o 'jsonpath={range .items[*]}{.metadata.namespace}{"|"}{.metadata.labels.app\.kubernetes\.io/name}{"|"}{.spec.hostNetwork}{"|"}{.status.podIP}{"|"}{.metadata.deletionTimestamp}{"\n"}{end}' 2>/dev/null
}

# Prints the trusted pod addresses (or, with "contested", the system pod addresses that are not
# trusted), one per line; fails if the query fails.
# An address that a non-trusted pod (not on the host network) also reports is NOT trusted: one of
# the two records is stale and there is no telling which. A terminating trusted pod stays trusted
# only until its grace period ends (its deletionTimestamp); a terminating non-trusted pod keeps
# its claim for as long as it is listed.
pod_addresses() { # trusted|contested
  local all
  all=$(all_pods) || return 1
  awk -F'|' -v mode="$1" -v now="$(date -u +%Y-%m-%dT%H:%M:%SZ)" -v extra="$(extra_namespaces | tr '\n' ' ')" '
    BEGIN { n = split(extra, e, " "); for (i = 1; i <= n; i++) ns[e[i]] = 1; ns["kube-system"] = 1 }
    $3 == "true" || $4 !~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ { next }
    ($1 in ns) || ($1 == "can-system" && $2 == "can-core") {
      if ($5 == "" || $5 > now) want[$4] = 1
      next
    }
    { claimed[$4] = 1 }
    END { for (ip in want) if (((ip in claimed) ? "contested" : "trusted") == mode) print ip }' <<<"$all" | sort -u
}

trusted_ips() { pod_addresses trusted; }

set_commands() { # newline separated addresses
  local list
  echo "flush set $TABLE_FAMILY $TABLE_NAME trusted4"
  list=$(printf '%s\n' "$1" | grep . | paste -sd, -)
  if [ -n "$list" ]; then
    echo "add element $TABLE_FAMILY $TABLE_NAME trusted4 { $list }"
  fi
}

load() { # nft commands: checked, then applied as one transaction
  printf '%s\n' "$1" | nft -c -f - && printf '%s\n' "$1" | nft -f -
}

# The whole table is replaced in one transaction: that also undoes what flushing the chains would
# not (a dormant table, a chain with another hook or priority, a changed set). If the pods cannot
# be listed the addresses already in the set are carried over.
apply() {
  local t="$TABLE_FAMILY $TABLE_NAME" tx ips
  tx="add table $t
delete table $t
$(rules)"
  ips=$(trusted_ips) || ips=$(set_elements | grep -E '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$')
  tx+=$'\n'$(set_commands "$ips")
  if ! load "$tx"; then
    err "the rules did not load; whatever was loaded before is unchanged"
    return 1
  fi
}

# 1: the pods could not be listed. 2: nft refused the new set.
sync_set() {
  local ips
  ips=$(trusted_ips) || return 1
  load "$(set_commands "$ips")" || return 2
}

# A chain listing without its traffic counters.
strip_counters() { sed -E 's/counter packets [0-9]+ bytes [0-9]+/counter/'; }

list_chains() {
  nft list chain "$TABLE_FAMILY" "$TABLE_NAME" input && nft list chain "$TABLE_FAMILY" "$TABLE_NAME" forward
}

# What list_chains must print: rules() loaded into a new, empty network namespace (discarded at
# once, nothing on the host changes) and listed by the same nft, so no nft version's formatting is
# assumed. Computed once per process.
EXPECTED=''
load_expected() {
  [ -z "$EXPECTED" ] || return 0
  local t="$TABLE_FAMILY $TABLE_NAME" out
  out=$(rules | unshare --net sh -c "nft -f - && nft list chain $t input && nft list chain $t forward") || return 1
  EXPECTED=$(strip_counters <<<"$out")
}

# Succeeds when the table is live and both chains hold exactly what rules() loads, line for line.
# Sets RULES_STATE: ok, missing, dormant (loaded but hooked to nothing), changed, or unknown (no
# reference to compare with).
RULES_STATE=''
rules_intact() {
  local table have
  if ! table=$(nft list table "$TABLE_FAMILY" "$TABLE_NAME" 2>/dev/null); then
    RULES_STATE=missing
  elif grep -Eq '^[[:space:]]*flags .*dormant' <<<"$table"; then
    RULES_STATE=dormant
  elif ! load_expected; then
    RULES_STATE=unknown
  elif have=$(list_chains 2>/dev/null) && [ "$(strip_counters <<<"$have")" = "$EXPECTED" ]; then
    RULES_STATE=ok
  else
    RULES_STATE=changed
  fi
  [ "$RULES_STATE" = ok ]
}

set_elements() {
  nft list set "$TABLE_FAMILY" "$TABLE_NAME" trusted4 2>/dev/null | tr -d '\n' |
    sed -n 's/.*elements = {\([^}]*\)}.*/\1/p' | tr -s ', \t' '\n' | grep . | sort -u
}

run() {
  local sig last='' next=0 burst=0 tick=0 failed=0 rc blind=''
  while true; do
    if [ $((tick % 5)) -eq 0 ] && ! rules_intact; then
      # Only rules known to be wrong are replaced: "unknown" says nothing about them.
      case $RULES_STATE in
        missing | dormant | changed)
          log "rules $RULES_STATE: loading them"
          apply || true
          ;;
        *)
          [ -n "$blind" ] || log "cannot compare the rules (needs unshare --net as root): leaving them"
          blind=1
          ;;
      esac
    fi
    tick=$((tick + 1))
    # The CNI keeps one file per allocated pod address: a change means pods came or went, so
    # refresh at once (and for a few seconds more, while the API catches up).
    # shellcheck disable=SC2012
    sig=$(ls "$CNI_STATE" 2>/dev/null | tr '\n' ' ')
    if [ "$sig" != "$last" ]; then
      burst=8
      last=$sig
    fi
    if [ "$burst" -gt 0 ] || [ "$SECONDS" -ge "$next" ]; then
      rc=0
      sync_set || rc=$?
      # Logged when the outcome changes, not on every attempt.
      if [ "$rc" -ne "$failed" ]; then
        case $rc in
          0) log "trusted set updated again" ;;
          1) log "cannot list pods: keeping the current trusted set" ;;
          *) log "nft could not update the trusted set: keeping the current one" ;;
        esac
        failed=$rc
      fi
      next=$((SECONDS + INTERVAL))
      [ "$burst" -eq 0 ] || burst=$((burst - 1))
    fi
    sleep 1
  done
}

check() {
  local bad=0 want have missing stale contested
  problem() {
    echo "problem=$*"
    bad=1
  }
  rules_intact || true
  echo "rules=$RULES_STATE"
  case $RULES_STATE in
    ok) ;;
    missing) problem "the isolation rules are not loaded" ;;
    dormant) problem "the isolation table is dormant: nothing is filtered" ;;
    changed) problem "the isolation rules differ from the expected ones" ;;
    *) problem "cannot build the reference rules to compare with (needs unshare --net as root)" ;;
  esac
  if ip link show dev "$POD_BRIDGE" >/dev/null 2>&1; then
    echo "bridge=present"
  else
    echo "bridge=missing"
    problem "interface $POD_BRIDGE not found: the rules match nothing"
  fi
  if command -v "$SYSTEMCTL" >/dev/null 2>&1; then
    local unit service=active
    for unit in "${UNITS[@]}"; do
      "$SYSTEMCTL" is-enabled --quiet "$unit" || {
        service=inactive
        problem "$unit is not enabled: isolation would not come back after a reboot"
      }
    done
    "$SYSTEMCTL" is-active --quiet can-firewall-sync.service || {
      service=inactive
      problem "can-firewall-sync.service is not running"
    }
    if "$SYSTEMCTL" is-failed --quiet can-firewall.service; then
      service=failed
      problem "can-firewall.service failed: the rules were not loaded by it"
    fi
    echo "service=$service"
  else
    echo "service=n/a"
  fi
  if want=$(trusted_ips); then
    have=$(set_elements)
    missing=$(comm -23 <(printf '%s\n' "$want" | grep .) <(printf '%s\n' "$have" | grep .) | grep -c .)
    stale=$(comm -13 <(printf '%s\n' "$want" | grep .) <(printf '%s\n' "$have" | grep .) | grep -c .)
    echo "trusted=$(printf '%s\n' "$have" | grep -c .)"
    echo "missing=$missing"
    echo "stale=$stale"
    [ "$missing" -eq 0 ] || problem "$missing system pod address(es) are not trusted yet"
    [ "$stale" -eq 0 ] || problem "$stale trusted address(es) belong to no system pod"
    contested=$(pod_addresses contested | grep -c .)
    echo "contested=$contested"
    [ "$contested" -eq 0 ] || problem "$contested system pod address(es) are also reported by another pod and so are not trusted"
  else
    problem "cannot list pods"
  fi
  if [ "$bad" -eq 0 ]; then
    echo "status=ok"
  else
    echo "status=fail"
  fi
  return "$bad"
}

write_units() {
  install -d -m 0755 "$UNIT_DIR"
  cat >"$UNIT_DIR/can-firewall.service" <<UNIT
[Unit]
Description=Company in a Can: pod-to-node isolation rules
# After anything that may flush the ruleset at boot, before the pods start.
After=local-fs.target nftables.service ufw.service
Before=k3s.service

[Service]
Type=oneshot
RemainAfterExit=yes
ExecStart=$SELF apply

[Install]
WantedBy=multi-user.target
UNIT
  cat >"$UNIT_DIR/can-firewall-sync.service" <<UNIT
[Unit]
Description=Company in a Can: trusted system pod addresses for the isolation rules
After=can-firewall.service
Wants=can-firewall.service

[Service]
ExecStart=$SELF run
Restart=always
RestartSec=2

[Install]
WantedBy=multi-user.target
UNIT
}

# Waits for the pod bridge and the system pods, so the rules are never loaded with an empty
# trusted set on a running cluster (CoreDNS and Traefik would lose the API).
wait_for_cluster() {
  local deadline=$((SECONDS + WAIT))
  while true; do
    if ip link show dev "$POD_BRIDGE" >/dev/null 2>&1 && [ -n "$(trusted_ips)" ]; then
      return 0
    fi
    [ "$SECONDS" -lt "$deadline" ] || return 1
    sleep 2
  done
}

verify() {
  local want
  rules_intact || {
    err "verify: the rules are not loaded as expected ($RULES_STATE)"
    return 1
  }
  # Several attempts: a system pod may be replaced between listing and comparing.
  for _ in 1 2 3; do
    if sync_set && want=$(trusted_ips) && [ -n "$want" ] &&
      [ -z "$(comm -23 <(printf '%s\n' "$want") <(set_elements))" ] &&
      "${KC[@]}" --request-timeout=5s get --raw=/readyz >/dev/null 2>&1; then
      return 0
    fi
    sleep 2
  done
  err "verify: the API server or the system pod addresses could not be confirmed"
  return 1
}

restore() { # previous "nft list table" output, possibly empty
  local t="$TABLE_FAMILY $TABLE_NAME"
  load "add table $t
delete table $t
$1" || nft delete table "$TABLE_FAMILY" "$TABLE_NAME" 2>/dev/null || true
}

# Undoes a failed unit installation: every unit goes back to the enabled and running state it
# had before, with its previous unit file, and the previous table is loaded again. A unit that was
# running is restarted, and runs the script that is installed now (the previous one is not kept):
# its rules then replace the table put back here.
# Reads SAVED (unit name to previous file), WAS_ENABLED and WAS_ACTIVE, set by install_all.
roll_back_units() { # previous table
  local unit
  for unit in "${UNITS[@]}"; do
    [[ " $WAS_ENABLED " == *" $unit "* ]] || "$SYSTEMCTL" disable "$unit" >/dev/null 2>&1 || true
    [[ " $WAS_ACTIVE " == *" $unit "* ]] || "$SYSTEMCTL" stop "$unit" >/dev/null 2>&1 || true
  done
  restore "$1"
  for unit in "${UNITS[@]}"; do
    if [ -n "${SAVED[$unit]:-}" ]; then
      printf '%s\n' "${SAVED[$unit]}" >"$UNIT_DIR/$unit"
    else
      rm -f "${UNIT_DIR:?}/${unit:?}"
    fi
  done
  "$SYSTEMCTL" daemon-reload >/dev/null 2>&1 || true
  for unit in $WAS_ENABLED; do
    "$SYSTEMCTL" enable "$unit" >/dev/null 2>&1 || err "could not enable $unit again"
  done
  for unit in $WAS_ACTIVE; do
    "$SYSTEMCTL" restart "$unit" >/dev/null 2>&1 || err "could not restart $unit"
  done
}

install_all() {
  local previous unit
  if ! wait_for_cluster; then
    err "no pod bridge ($POD_BRIDGE) or no system pods after ${WAIT}s: nothing was changed"
    return 1
  fi
  previous=$(nft list table "$TABLE_FAMILY" "$TABLE_NAME" 2>/dev/null || true)
  apply || return 1
  if ! verify; then
    restore "$previous"
    err "rolled back"
    return 1
  fi
  local -A SAVED=()
  local WAS_ENABLED='' WAS_ACTIVE=''
  for unit in "${UNITS[@]}"; do
    [ ! -f "$UNIT_DIR/$unit" ] || SAVED[$unit]=$(cat "$UNIT_DIR/$unit")
    ! "$SYSTEMCTL" is-enabled --quiet "$unit" 2>/dev/null || WAS_ENABLED+="$unit "
    case $("$SYSTEMCTL" is-active "$unit" 2>/dev/null) in
      active | activating | reloading) WAS_ACTIVE+="$unit " ;;
    esac
  done
  write_units
  if ! { "$SYSTEMCTL" daemon-reload && "$SYSTEMCTL" enable "${UNITS[@]}" && "$SYSTEMCTL" restart "${UNITS[@]}"; }; then
    roll_back_units "$previous"
    err "systemd refused the units; rolled back"
    return 1
  fi
  log "installed: pods can no longer reach node services (system pods: API server and DNS only)"
}

disable_all() {
  "$SYSTEMCTL" disable --now "${UNITS[@]}" >/dev/null 2>&1 || true
  nft delete table "$TABLE_FAMILY" "$TABLE_NAME" 2>/dev/null || true
  if nft list table "$TABLE_FAMILY" "$TABLE_NAME" >/dev/null 2>&1; then
    err "could not delete the table"
    return 1
  fi
}

uninstall_all() {
  disable_all || return 1
  rm -f "$UNIT_DIR/can-firewall.service" "$UNIT_DIR/can-firewall-sync.service" "$SELF"
  "$SYSTEMCTL" daemon-reload >/dev/null 2>&1 || true
}

main() {
  case "${1:-}" in
    rules) rules ;;
    apply) apply ;;
    sync) sync_set ;;
    run) run ;;
    install) install_all ;;
    check) check ;;
    disable) disable_all ;;
    uninstall) uninstall_all ;;
    *)
      echo "usage: can-firewall rules|apply|sync|run|install|check|disable|uninstall" >&2
      return 2
      ;;
  esac
}

main "$@"
CAN_FIREWALL_SCRIPT
chmod 0755 /usr/local/sbin/can-firewall.new
mv /usr/local/sbin/can-firewall.new /usr/local/sbin/can-firewall
/usr/local/sbin/can-firewall install || {
  echo "CAN_ERROR: node isolation is not installed. Fix the cause above, then run on the server: bash /usr/local/sbin/can-bootstrap.sh" >&2
  exit 1
}

echo "$want_config" > /var/lib/can/k3s-config.applied

step backup-dirs
# can-core (uid 65532, deploy/can-core/can-core.yaml volume can-dumps) writes its dumps here.
install -d -o 65532 -g 65532 -m 0700 /var/lib/can/dumps
install -d -m 0700 /etc/can/backup.d
cat > /etc/can/backup.d/README <<'CAN_BACKUP_README'
Credentials of the restic backup timer (docs/backup-restore.md); empty until backup is set up.
can-core writes its dumps to /var/lib/can/dumps.
CAN_BACKUP_README

step complete
echo "$K3S_VERSION" > /var/lib/can/bootstrap.done
echo "CAN_BOOTSTRAP_DONE ${K3S_VERSION}"
